//! HA's translations and icons for the integrations `hars` knows
//! (`frontend/get_translations`, `frontend/get_icons`), English only. The
//! data is generated by `scripts/gen-i18n.py` as ready-made JSON pieces, so
//! an answer is joined, not parsed or kept in memory.

use crate::i18n_data::{ICONS, TRANSLATIONS};

/// Strings of `hars`'s own, beside HA's for the same `(category,
/// domain)`: what a flow says where `hars` stops and HA would go on.
static OWN: &[(&str, &str, &str)] = &[
    (
        "config",
        "hue",
        r#""component.hue.config.abort.not_v2_bridge":"This bridge only has the first version of the Hue API, which hars can't use. hars needs a bridge with the current Hue software (the square bridge)""#,
    ),
    (
        "config",
        "lifx",
        r#""component.lifx.config.abort.unsupported_device":"hars can't run this LIFX product yet. It runs single-zone bulbs, colour and white: not light strips, tiles, ceilings, the Clean's HEV light or Night Vision's infrared""#,
    ),
];

/// The entry for `(category, domain)` in a sorted table.
fn find(
    table: &'static [(&str, &str, &str)],
    category: &str,
    domain: &str,
) -> Option<&'static str> {
    table
        .binary_search_by(|(c, d, _)| (*c, *d).cmp(&(category, domain)))
        .ok()
        .map(|i| table[i].2)
}

/// Each domain once, in order.
fn unique<'a>(domains: &[&'a str]) -> Vec<&'a str> {
    let mut seen = Vec::with_capacity(domains.len());
    for d in domains {
        if !seen.contains(d) {
            seen.push(*d);
        }
    }
    seen
}

/// `{"resources": {flattened key: string}}` for `category` across
/// `domains`, as HA's translation cache merges them.
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) fn translations(category: &str, domains: &[&str]) -> String {
    translations_with_plugins(category, domains, None)
}

/// Like [`translations`], also merging strings from `hars_plugins` and any
/// installed plugins.
pub(crate) fn translations_with_plugins(
    category: &str,
    domains: &[&str],
    plugins: Option<&ha_integrations::plugin::PluginManager>,
) -> String {
    let mut out = String::from(r#"{"resources":{"#);
    let mut first = true;
    for d in unique(domains) {
        let own = OWN.iter().find(|(c, o, _)| *c == category && o == &d);
        let store = (d == ha_integrations::plugin::STORE_DOMAIN && plugins.is_some())
            .then(|| ha_integrations::plugin::store::store_translations(category))
            .flatten();
        let plugin_loaded = plugins.and_then(|p| p.get(d));
        let plugin_str = plugin_loaded
            .as_ref()
            .and_then(|p| p.translations_for(category));
        for body in [
            find(TRANSLATIONS, category, d),
            own.map(|o| o.2),
            store,
            plugin_str,
        ]
        .into_iter()
        .flatten()
        {
            if !first {
                out.push(',');
            }
            out.push_str(body);
            first = false;
        }
    }
    out.push_str("}}");
    out
}

/// `{"resources": {domain: icons}}` for `category` across `domains`.
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) fn icons(category: &str, domains: &[&str]) -> String {
    icons_with_plugins(category, domains, None)
}

/// Like [`icons`], also merging icon trees from installed plugins.
pub(crate) fn icons_with_plugins(
    category: &str,
    domains: &[&str],
    plugins: Option<&ha_integrations::plugin::PluginManager>,
) -> String {
    let mut out = String::from(r#"{"resources":{"#);
    let mut first = true;
    for d in unique(domains) {
        let plugin_loaded = plugins.and_then(|p| p.get(d));
        let tree = find(ICONS, category, d)
            .or_else(|| plugin_loaded.as_ref().and_then(|p| p.icons_for(category)));
        if let Some(tree) = tree {
            if !first {
                out.push(',');
            }
            out.push('"');
            out.push_str(d);
            out.push_str("\":");
            out.push_str(tree);
            first = false;
        }
    }
    out.push_str("}}");
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn tables_are_sorted_and_valid_json() {
        for table in [TRANSLATIONS, ICONS] {
            assert!(
                table
                    .windows(2)
                    .all(|w| (w[0].0, w[0].1) < (w[1].0, w[1].1))
            );
        }
        for (_, _, body) in TRANSLATIONS {
            serde_json::from_str::<Value>(&format!("{{{body}}}")).unwrap();
        }
        for (_, _, tree) in ICONS {
            serde_json::from_str::<Value>(tree).unwrap();
        }
    }

    #[test]
    fn answers_like_has_translation_cache() {
        let v: Value = serde_json::from_str(&translations(
            "entity_component",
            &["weather", "sun", "weather", "nope"],
        ))
        .unwrap();
        let r = &v["resources"];
        assert_eq!(
            r["component.weather.entity_component._.state.partlycloudy"],
            "Partly cloudy"
        );
        assert_eq!(
            r["component.sun.entity_component._.state.above_horizon"],
            "Above horizon"
        );
        // Titles come from the manifest when en.json has none.
        let v: Value = serde_json::from_str(&translations("title", &["met", "api"])).unwrap();
        assert_eq!(v["resources"]["component.api.title"], "Home Assistant API");
        assert!(v["resources"]["component.met.title"].is_string());
        let v: Value = serde_json::from_str(&icons("services", &["light"])).unwrap();
        assert_eq!(
            v["resources"]["light"]["turn_on"]["service"],
            "mdi:lightbulb-on"
        );
        assert_eq!(translations("entity", &["nope"]), r#"{"resources":{}}"#);
    }
}
